insert into public.tienda_contenidos(id,kind,data,position,published) values
('pregunta-1','faq','{"question":"¿El precio incluye el envío?","answer":"Sí. Cada presentación tiene un precio final con envío incluido. Podés ver el total antes de pagar."}'::jsonb,0,true),
('pregunta-2','faq','{"question":"¿Cómo se despacha mi pedido?","answer":"Preparamos y embalamos tu pedido en San Rafael, Mendoza. Una vez despachado, podrás consultar el código de seguimiento en el detalle de tu pedido."}'::jsonb,10,true),
('pregunta-3','faq','{"question":"¿Cuál es la diferencia entre los huevos de consumo y los fértiles?","answer":"En el catálogo los separamos por uso: para tu mesa o para incubar. Si vas a criar codornices, elegí una de las presentaciones de huevos fértiles."}'::jsonb,20,true),
('pregunta-4','faq','{"question":"¿Dónde puedo comprar en persona?","answer":"En la sección Dónde comprar podés elegir tu localidad y ver los comercios que ofrecen nuestros productos. Consultá disponibilidad con el comercio."}'::jsonb,30,true),
('pregunta-5','faq','{"question":"¿Puedo comprar por mayor?","answer":"Sí. Escribinos por WhatsApp y contanos qué tipo de comercio tenés, en qué localidad y qué cantidades necesitás."}'::jsonb,40,true),
