-- Tienda web: estados del catálogo, contenido público y destino en pedidos de prueba.
-- Solo objetos tienda_*; no cambia usuarios, credenciales ni tablas de gestión.
begin;

alter table public.tienda_productos
 add column publication_state text,
 add constraint tienda_publication_consistency check (
  publication_state is null or
  (publication_state='published' and active) or
  (publication_state in ('draft','paused','archived') and not active)
 );
-- La fila anterior conserva su visibilidad. NULL identifica el estado heredado.
grant insert(publication_state),update(publication_state) on public.tienda_productos to authenticated;

alter table public.tienda_pedidos
 add column delivery_address jsonb,
 drop constraint tienda_pedidos_delivery_check,
 add constraint tienda_pedidos_delivery_check check (
  (delivery='simulated_pickup' and delivery_address is null) or
  (delivery='simulated_shipping' and delivery_address is not null and jsonb_typeof(delivery_address)='object'
   and delivery_address ?& array['province','city','postal_code','address','phone','reference'])
 );

create table public.tienda_contenidos (
 id text primary key check(id ~ '^[a-z0-9-]{1,64}$'),
 kind text not null check(kind in ('faq','location','recipe')),
 data jsonb not null check(jsonb_typeof(data)='object' and octet_length(data::text)<=16000),
 position integer not null default 0 check(position between 0 and 9999),
 published boolean not null default false,
 updated_at timestamptz not null default now()
);
create index tienda_contenidos_kind_position on public.tienda_contenidos(kind,position,id);
alter table public.tienda_contenidos enable row level security;
revoke all on public.tienda_contenidos from public,anon,authenticated;
grant select on public.tienda_contenidos to anon,authenticated;
grant insert(id,kind,data,position,published,updated_at),update(data,position,published,updated_at) on public.tienda_contenidos to authenticated;
create policy tienda_content_public on public.tienda_contenidos for select to anon,authenticated using(published);
create policy tienda_content_admin_read on public.tienda_contenidos for select to authenticated using ((select auth.uid()) in (select user_id from public.tienda_admins));
create policy tienda_content_admin_insert on public.tienda_contenidos for insert to authenticated with check ((select auth.uid()) in (select user_id from public.tienda_admins));
create policy tienda_content_admin_update on public.tienda_contenidos for update to authenticated using ((select auth.uid()) in (select user_id from public.tienda_admins)) with check ((select auth.uid()) in (select user_id from public.tienda_admins));

-- Copia única de los puntos y recetas de la web anterior, más preguntas iniciales.

commit;
